GestureType gesture_rf_predict_with_votes(const GestureRfFeatures *features,
                                          uint8_t votes[5])
{
    uint32_t tree_id;
    uint8_t best_class = 0U;

    if (!features || !votes) {
        return GESTURE_NONE;
    }

    for (tree_id = 0U; tree_id < 5U; tree_id++) {
        votes[tree_id] = 0U;
    }

    for (tree_id = 0U; tree_id < GESTURE_RF_TREE_COUNT; tree_id++) {
        uint32_t offset = g_tree_offsets[tree_id];
        uint16_t node = 0U;

        while (g_right[offset + node] != RF_LEAF_NODE) {
            uint32_t array_index = offset + node;
            uint8_t feature_index = g_feature[array_index];
            if (features->value[feature_index] + RF_THRESHOLD_BIAS <= g_threshold[array_index]) {
                node++;
            } else {
                node = g_right[array_index];
            }
        }
        votes[g_feature[offset + node]]++;
    }

    for (tree_id = 1U; tree_id < 5U; tree_id++) {
        if (votes[tree_id] > votes[best_class]) {
            best_class = (uint8_t)tree_id;
        }
    }
    return (GestureType)best_class;
}
